INSERT OR REPLACE INTO products (id, name, description, price, category, image, is_active) VALUES ('p1771289338748', 'Pioneer DJM-S9 DJ mixer', 'Pioneer DJ s9 professional DJ Mixer MIDI Control Full assignable MIDI controls MAGVEL Fader Pro Performance Pads For dynamic live mixing, 16 multi-color touch pads give access to Hot Cue, Roll, Slice, Loop and more. Their optimized shape and seat switch connections Customizable FX Buttons Six customizable buttons on each side of the mixer, and two in the middle, trigger effects directly on your hardware. Fire up six dedicated Beat FX on the left banks, or replace them with other popular on-board FX. Filter FX Rotate the dial to add a high/low pass filter to FX on each channel, or use Serato DJ to switch to other filter FX like Dub Echo, Noise and Pitch. Style Levers Quickly turn effects on and off using the 2 large Style Levers 2 Built-In USB Soundcards Play back-to-back with other DJs seamlessly using the input switcher on top to switch between all four Serato DJ decks. Enhanced MIC Input The MIC input features Echo FX and high-quality circuitry to eliminate unwanted distortion. Clip ', 235000, 'Accessories', '', 1);
