INSERT OR REPLACE INTO products (id, name, description, price, category, image, is_active) VALUES ('p1771377545696', 'Pioneer DDJ-REV1', 'The DDJ-REV1 matches perfectly with the free Serato DJ Lite software, boasting a brand-new battle-style layout that’s easy to use and perfect for playing like a pro. The design of this 2-channel DJ controller emulates a professional DJM-S mixer + PLX turntable setup, including specialized features for open-format and scratch DJs. Key Features Deck 3/4 controlSupport for Serato DJ ProClass compliantFirmware Update Manager What’s in the box DDJ-REV1 USB cable Quick start guide Precautions for use', 50000, 'DJ Controllers', '', 1);
INSERT OR REPLACE INTO products (id, name, description, price, category, image, is_active) VALUES ('p1771299299985', 'Pioneer AlphaTheta DDJ-GRV6 4-channel Performance DJ Controller', 'Maximum Dimensions (W × D × H)	711.4 × 375.9 × 75.7 mm / 28.0” × 14.8” × 3.0” Main unit weight	4.6 kg / 10.2 lbs.  Frequency response 	20 Hz - 20 kHz (USB) S/N ratio	104 dB (USB) Total harmonic distortion	0.003% (USB) Power supply	DC 9 V, 3.0 A (USB power adapter) DC 5 V, 1.5 A (USB bus power) Accessories	USB cable (C to C) Overlay sheet Quick Start Guide Precautions for Use Warranty (for some regions) Compatible software	rekordbox for Mac/Windows rekordbox for iOS/Android Serato DJ Pro djay Pro for Mac/Windows djay for iOS Terminals Inputs	MIC × 1 (1/4″ TRS jack × 1) Outputs	MASTER × 2 (1/4″ TRS jack × 1, RCA × 1)  BOOTH × 1 (RCA × 1)  PHONES × 2 (1/4″ stereo jack × 1, 3.5 mm stereo mini jack × 1) USB	USB Type-C × 2 Performance Control Channels	4 Deck Control	4 / Dual Jog Wheel	206 mm Sampler	(rekordbox) 16 slot × 4 bank (Serato DJ Pro) 8 slot × 4 bank Hot Cues	8 Pad Modes	(rekordbox) Hot Cue, Stems, Beat Jump, Sampler, Keyboard, Pad FX, Beat Loop, Key Shift (Serato DJ Pro) Hot Cue, S', 130000, 'Accessories', '', 1);
