INSERT OR REPLACE INTO products (id, name, description, price, category, image, is_active) VALUES ('p1771535360949', 'Oraimo SpaceBuds Air OTW-324S 38', 'Core Specifications Model: OTW-324S Bluetooth Version: V5.4 Total Playtime: Up to 38 hours (6.5 hours single charge + 31.5 hours case) Charging: Type-C fast charging Sound Technology: Sound360 Spatial Sound, 10mm Dynamic Drivers Microphones: Dual-mic AI call noise cancellation Waterproof Rating: IPX4 Range: 10m  Oraimo Oraimo  +5 Additional Features Smart Earbud Finder: Locate misplaced buds via the app. Design: Half-in-ear comfort fit with an anti-lost silicone lanyard. App Support: oraimo sound app for customizations and EQ settings. Gaming: Dedicated low-latency game mode. ', 1700, 'Audio Equipment', '', 1);
INSERT OR REPLACE INTO products (id, name, description, price, category, image, is_active) VALUES ('p1771535797073', 'SpaceBuds lite OTW-324', 'Audio & Sound Driver Size: 10mm Dynamic Drivers Sound Technology: Sound360 Spatial Sound (provides a 360° immersive audio experience, customizable in the app) Microphones: Dual Mics with AI Call Noise Cancellation EQs: 5 Preset EQs and Custom EQ options via the Oraimo Sound App  Oraimo Oraimo  +2 Battery & Charging Total Playtime: Up to 38 hours (with charging case) Single Charge Playtime: Up to 6.5 hours Fast Charging: 10-minute charge = 2 hours of playback Charging Port: Type-C  Oraimo Oraimo  +1 Connectivity & Features Bluetooth Version: V5.4 Range: 10m Smart Features: Smart Earbud Finder (locates earbuds via app) App Support: Oraimo Sound App (for personalized Bluetooth naming, EQ, and controls) Game Mode: Low-latency mode Connection: Open-to-connect (instant pairing)  Oraimo Oraimo  +3 Design & Durability Fit: Half-In-Ear Weight: ~4g per earbud Water Resistance: IPX4 (Sweat & Splash Resistant - earbuds only) Extras: Anti-lost lanyard included', 1500, 'Audio Equipment', '', 1);
INSERT OR REPLACE INTO products (id, name, description, price, category, image, is_active) VALUES ('p1771537536375', 'Oraimo watch 5N OSW-806N wireless HD calling', 'Wireless HD Calling: Bluetooth 5.3 connectivity allows for clear, direct calls from the wrist, featuring contact syncing and quick dialing. Display: 2.01-inch TFT screen, 240x296 resolution, full-touch. Battery: 300mAh lithium polymer battery. Offers 7 days of normal usage and 30 days standby. Health Tracking: 24/7 monitoring for heart rate, blood oxygen (SpO2), stress, sleep, and women''s health. Fitness: 100+ sport modes (running, cycling, dancing, etc.). Durability: IP68 waterproof and dustproof rating (resistant to water, splashes, and sweat). Dimensions: 47.8 x 39.2 x 10.95 mm. App & Compatibility: Pairs via Bluetooth 5.3 to the Oraimo Health app (Android 6.0+, iOS 12.0+). Other Features: Music control, camera remote control, alarm clock, stopwatch, timer, and calculator', 3000, 'Accessories', '', 1);
INSERT OR REPLACE INTO products (id, name, description, price, category, image, is_active) VALUES ('p1771536483698', 'Oraimo watch 2R OSW-30 with wireless HD calling', 'Display: 1.39-inch TFT Screen, 360*360 resolution, 500 nits brightness. Calling/Connectivity: Bluetooth V5.2 with Bluetooth Calling (HD call stability), 100-contact management. Battery: 260mAh Lithium polymer battery, 7-day standby time, 2-hour charging time. Health & Fitness: 120+ sports modes, 24-hour heart rate, SpO2 (blood oxygen), sleep tracking, and breathing exercises. Design & Durability: 464611mm size, 39.8g weight, IP68 rated for dust and water resistance. Smart Features: SOS emergency call (triple-click), quick replies, 100+ watch faces, music control, camera control, and weather updates. Compatibility: Android 6.0 or later and iOS 12.0 or later.  Oraimo Oraimo  +5 The device is built with an ABS/PC body and a 22mm detachable silicone strap. It supports quick replies via the Oraimo Health app.', 3200, 'Accessories', '', 1);
