INSERT OR REPLACE INTO products (id, name, description, price, category, image, is_active) VALUES ('p1771534895210', 'DELL 5410-14 10THGEN', 'Processor - 10th Gen Intel Core i5-10210U (1.6GHz base, up to 4.2GHz with Turbo Boost, Quad-Core, 6MB Cache)-Display 14-inch Full HD (1920 x 1080) Anti-Glare Display with narrow bezels for an immersive viewing experience-Memory 16GB DDR4 RAM, offering smooth multitasking capabilities-Storage 256GB PCIe NVMe SSD for quick boot-up and rapid file access-Graphics Integrated Intel UHD Graphics 620 for crisp visuals and efficient performance in everyday applications-Operating System FreeDOS (ready for your preferred OS installation)-Camera Infrared (IR) HD Webcam for high-quality video calls and enhanced security features-Audio Stereo speakers with Waves-MaxxAudio Pro for a rich audio experience-Connectivity -Intel Wi-Fi 6 (802.11ax)-Bluetooth 5.1-USB-C with Power Delivery and DisplayPort support-USB 3.1 Gen 1 (Type-A)-HDMI 1.4-RJ-45 Ethernet port-MicroSD card reader-Headphone/microphone combo jack ', 35000, 'Laptops', '', 1);
INSERT OR REPLACE INTO products (id, name, description, price, category, image, is_active) VALUES ('p1771540393680', '80W SpaceBox Pro OBS-682 ', 'Speaker Output: 80W RMS (4″ sub + 2x 2″ tweeters + 2x 3″ radiators) Bluetooth: Version 5.4 (10m range) Battery: 5000mAh/7.4V Playtime: Up to 6 hours (max volume), 10 hours (medium), up to 27 hours with boost mode Charging: 35W fast charging (2 hours) Inputs: Bluetooth, AUX-in, Memory Card, USB Drive, 6.35mm Mic-in Powerbank Function: 10W output Dimensions: 328 x 152 x 138 mm Features: IPX4 rating, Oraimo Sound App control, TWS pairing, LED light show, includes shoulder strap', 10000, 'Speakers', '', 1);
