INSERT OR REPLACE INTO products (id, name, description, price, category, image, is_active) VALUES ('p1771565349801', 'Pioneer DJ DDJ-REV5 4-deck DJ Controller', 'Category	Feature Compatible DJ Software	- Serato DJ Pro (license required) - rekordbox (Mac/Windows, iOS/Android) System Requirements	Visit serato.com and rekordbox.com for specifications Accessories	AC Adaptor, Power Cord, USB Cable, Warranty (select regions), Quick Start Guide, Precautions for Use, Serato DJ Pro Pitch ’n Time DJ Voucher Dimensions	Width: 28.98 in (736 mm), Depth: 14.85 in (377 mm), Height: 2.89 in (73.4 mm), Weight: 13.67 lb (6.2 kg) Audio Specs	Soundcard: 24-bit/48 kHz, Signal-to-Noise Ratio: 110 dB, Distortion: < 0.003% (USB), Frequency Range: 20 Hz–20 kHz Power	DC 5V, 3000 mA (via USB Type-C) Performance Control	Channels: 2, Deck Control: 4 (Dual), Jog Wheel: 206 mm, Sampler: 8 slots x 4 banks, Hot Cues: 8, Auto Loop/Auto Beat Loop: Yes Pad Modes (rekordbox)	Hot Cue, Pad FX 1, Beat Jump, Sampler, Keyboard, Piano Play, Beat Loop, Sample Scratch Pad Modes (Serato)	Hot Cue, Roll, Saved Loop, Sampler, Pitch Play, Piano Play, Stems, Scratch Bank, Saved Flip, Slicer Loo', 220000, 'DJ Controllers', '', 1);
INSERT OR REPLACE INTO products (id, name, description, price, category, image, is_active) VALUES ('p1771566145861', 'Rane one DJ Controller', 'The Rane one dj controller  is a premium, motorized DJ controller designed for a vinyl-like experience, offering a highly tactile and professional performance for scratch DJs and turntablists.  The ONE incorporates two 7.2″ motorized turntable platters for a traditional vinyl feeling, complete with customizable (low/high) torque settings. The unit provides an authentic, tactile control over your music and performance with the foundation art of DJing at its very core, including a traditional turntable plunger style start/stop button.  Other notable features include 8 multicolor velocity-sensitive performance pads per deck, each assignable to Hot Cues, Saved Loops, Roll, Sampler, Slicer, and Serato’s Scratch Bank feature. There are six radio-style FX buttons, which can be activated in any combination. Each channel offers a 3-band dynamic EQ and high/low pass filters, as well as dedicated loop controls.  Benefits At a Glance 7.2″ motorized platters with quick-release acrylic disks Trusted', 290000, 'DJ Controllers', '', 1);
INSERT OR REPLACE INTO products (id, name, description, price, category, image, is_active) VALUES ('p1771537098798', 'Oraimo BoomPop Lite(White B)Headphones OHP-317', 'Battery Life: Up to 60-65 hours playtime. Fast Charge: 10-minute charge provides 600 minutes (10 hours) of playback. Connectivity: Bluetooth 5.3, 3.5mm AUX cable, and dual-device connection. Audio: 40mm drivers with Sound360 Spatial Audio. Microphone: AI-powered Environmental Noise Cancellation (ENC). Design: Foldable, retractable, with soft ear cushions. Game Mode: Low-latency mode. Charging Port: USB Type-C. Range:   10 meters.', 2500, 'Audio Equipment', '', 1);
INSERT OR REPLACE INTO products (id, name, description, price, category, image, is_active) VALUES ('p1771658024061', 'Refurbished Apple MacBook Pro 2012 13″, Intel Core i5 processor, 4 GB RAM, 500 GB Hard Drive, Intel HD 3000 Graphics, Mac OS', 'Display 13.3-inch (diagonal) LED-backlit glossy widescreen display with support for millions of colors Supported resolutions: 1280 by 800 (native), 1152 by 720, 1024 by 640, and 800 by 500 pixels at 16:10 aspect ratio; 1024 by 768, 800 by 600, and 640 by 480 pixels at 4:3 aspect ratio; 1024 by 768, 800 by 600, and 640 by 480 pixels at 4:3 aspect ratio stretched; 720 by 480 pixels at 3:2 aspect ratio; 720 by 480 pixels at 3:2 aspect ratio stretched Graphics and video support Intel HD Graphics 3000 with 384MB of DDR3 SDRAM shared with main memory5 Dual display and video mirroring: Simultaneously supports full native resolution on the built-in display and up to 2560 by 1600 pixels on an external display, both at millions of colors FaceTime HD camera Thunderbolt port Thunderbolt digital video output Native Mini DisplayPort output DVI output using Mini DisplayPort to DVI Adapter (optional) VGA output using Mini DisplayPort to VGA Adapter (optional) Dual-link DVI output using Mini DisplayPor', 20000, 'Laptops', '', 1);
